    /**
     * @method
     * @name jupiter#fetchMarkets
     * @description maps the most liquid verified solana tokens to TOKEN/USDC spot markets
     * @see https://dev.jup.ag/docs
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public async override Task<List<ccxt.MarketInterface>> FetchMarkets(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "query", "verified" },
        };
        List<object> response = await this.publicGetTokensV2Tag(this.extend(request, parameters));
        //
        //     [
        //         { "id": "So11111111111111111111111111111111111111112", "name": "Wrapped SOL", "symbol": "SOL", "decimals": 9, "liquidity": 946221959.13, "usdPrice": 116.65, ... },
        //         ...
        //     ]
        //
        // symbols are not unique even among verified tokens (two WBTC mints), keep the deepest one
        // some tokens omit liquidity, and python's sort_by raises on a missing key
        List<object> withLiquidity = new List<object>() {};
        for (int i = 0; isLessThan(i, getArrayLength(response)); postFixIncrement(ref i))
        {
            ((IList<object>)withLiquidity).Add(this.extend(getValue(response, i), new Dictionary<string, object>() {
                { "liquidity", this.safeNumber(getValue(response, i), "liquidity", 0) },
            }));
        }
        List<object> tokens = this.sortBy(withLiquidity, "liquidity", true);
        string? quoteMint = this.safeString(this.options, "quoteMint");
        Int64? limit = this.safeInteger(this.options, "marketsLimit", 300);
        List<object> result = new List<object>() {};
        Dictionary<string, object> seen = new Dictionary<string, object>() {};
        object numMarkets = 0; // not result.length, php transpiles that to strlen
        for (int i = 0; isLessThan(i, getArrayLength(tokens)); postFixIncrement(ref i))
        {
            if (isTrue(isGreaterThanOrEqual(numMarkets, limit)))
            {
                break;
            }
            Dictionary<string, object> market = this.parseMarket(getValue(tokens, i));
            string? symbol = this.safeSymbol(null, market);
            if (isTrue(isTrue(!isEqual(this.safeString(market, "baseId"), quoteMint)) && !isTrue((inOp(seen, symbol)))))
            {
                ((IDictionary<string,object>)seen)[(string)symbol] = true;
                ((IList<object>)result).Add(market);
                numMarkets = add(numMarkets, 1);
            }
        }
        return ccxt.BaseExchange.ToMarketInterfaceList(result);
    }

